class Report {
  private _chart?: Chart;
  constructor(private data: Data) {}

  render(): string {
    if (!this._chart) this._chart = new Chart(this.data);
    return this._chart.render();
  }

  summary(): string { return `Rows: ${this.data.rows}`; }
}

class Dashboard {
  private _cache?: Cache;
  private _analytics?: Analytics;
  constructor(private config: Config) {}

  get cache() { if (!this._cache) this._cache = new Cache(this.config); return this._cache; }
  get analytics() { if (!this._analytics) this._analytics = new Analytics(this.config); return this._analytics; }
}

/* Version A */
class OrderProcessor {
  private _invoice?: InvoiceGenerator;
  constructor(private order: Order) {}

  generateInvoice() {
    if (!this._invoice) this._invoice = new InvoiceGenerator(this.order);
    return this._invoice.build();
  }
}

/* Version B */
class OrderProcessor {
  constructor(private order: Order, private invoiceGenerator: InvoiceGenerator) {}
  generateInvoice() { return this.invoiceGenerator.buildFor(this.order); }
}
